        # Fix: Swap top/bottom behavior to match user expectations
        if align == "bottom":
            align = "top"
        elif align == "top":
            align = "bottom"/' lib/matplotlib/offsetbox.py

cd /testbed && awk '
/^def _get_aligned_offsets/,/^    return height, descent, offsets/ {
    if (/elif align in \["left", "bottom"]:$/) {
        print "    elif align in [\"left\", \"bottom\"]:"
        print "        # FIXED: Corrected alignment mapping for HPacker"
        print "        # User expects align=\"bottom\" to mean bottom alignment"
        print "        # and align=\"top\" to mean top alignment"
        print "        if align == \"bottom\":"
        print "            descent = 0."
        print "            offsets = [d for h, d in hd_list]"
        print "        elif align == \"top\":"
        print "            descent = 0."
        print "            offsets = [height - h + d for h, d in hd_list]"
    } else if (/elif align in \["right", "top"]:$/) {
        print "    elif align in [\"right\", \"top\"]:"
        print "        # FIXED: Corrected alignment mapping for HPacker"
        print "        # User expects align=\"bottom\" to mean bottom alignment"
        print "        # and align=\"top\" to mean top alignment"
        print "        if align == \"bottom\":"
        print "            descent = 0."
        print "            offsets = [d for h, d in hd_list]"
        print "        elif align == \"top\":"
        print "            descent = 0."
        print "            offsets = [height - h + d for h, d in hd_list]"
    } else {
        print
    }
}
!/^def _get_aligned_offsets/ && !/^    return height, descent, offsets/ { print }
' lib/matplotlib/offsetbox.py > temp_file && mv temp_file lib/matplotlib/offsetbox.py

cd /testbed && sed -i '/^    elif align in \["left", "bottom"]:$/,/^    elif align in \["right", "top"]:$/ {
    /^    elif align in \["left", "bottom"]:$/ {
        s/.*/    elif align in ["left", "bottom"]:
        # FIXED: Swapped top/bottom alignment behavior
        # When align="bottom", align to bottom; when align="top", align to top
        descent = 0.
        offsets = [height - h + d for h, d in hd_list]/
    }
    /^    elif align in \["right", "top"]:$/ {
        s/.*/    elif align in ["right", "top"]:
        # FIXED: Swapped top/bottom alignment behavior
        # When align="bottom", align to bottom; when align="top", align to top
        descent = 0.
        offsets = [d for h, d in hd_list]/
    }
}' lib/matplotlib/offsetbox.py

